Definition dn_pass_post (t4 t5 t6 a0 a1 a2 a3 a4 a5 a6 s0 s1 s5 s6 : word) (m : word -> option byte) (z sh a' rp' : Z) (P : Z -> list word -> Prop) : machine_state -> Prop :=
  fun ms' => exists (c' : Z) (xs' : list word) t4' t5' t6' m',
      ms' = MS (mkR ra sp gp tp (Z_to_bv 64 sh) (Z_to_bv 64 c') (Z_to_bv 64 (1000000000 / 2 ^ sh)) s0 s1 a0 a1 a2 a3 a4 a5 a6 (Z_to_bv 64 (2 ^ sh - 1)) (Z_to_bv 64 z) (Z_to_bv 64 a') s4 s5 s6 (Z_to_bv 64 rp') s8 s9 s10 s11
             (Z_to_bv 64 z) t4' t5' t6') F (Z_to_bv 64 0xb58dc) fc None m' (seg_rom rsegs)
      /\ munch [(X, X + 8192)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u32arr rsegs m' X xs' /\ length xs' = 2048%nat /\ w32 xs' /\ (0 <= c' < 1000000000)%Z /\ P c' xs'.

Lemma dn_gen : forall (n : nat) (t4 t5 t6 a0 a1 a2 a3 a4 a5 a6 s0 s1 s5 s6 : word) m (a z k c rp sh : Z) (xs : list word),
  mem_inv rsegs m -> u32arr rsegs m X xs -> length xs = 2048%nat -> w32 xs ->
  (0 <= a < 2048)%Z -> (0 <= z < 2048)%Z -> (0 <= k < 2048)%Z -> (0 <= c < 1000000000)%Z -> (sh = 1 \/ sh = 9)%Z -> (-4000 <= rp <= 4000)%Z ->
  ((z - k) mod 2048 = Z.of_nat (S n))%Z -> ((z - k) mod 2048 <= (a - k) mod 2048)%Z ->
  evt rsegs (dn_pass_post t4 t5 t6 a0 a1 a2 a3 a4 a5 a6 s0 s1 s5 s6 m z sh a rp (fun c' xs' => nth_error xs' (Z.to_nat a) = nth_error xs (Z.to_nat a)))
    (MS (mkR ra sp gp tp (Z_to_bv 64 sh) (Z_to_bv 64 c) (Z_to_bv 64 (1000000000 / 2 ^ sh)) s0 s1 a0 a1 a2 a3 a4 a5 a6 (Z_to_bv 64 (2 ^ sh - 1)) (Z_to_bv 64 z) (Z_to_bv 64 a) s4 s5 s6 (Z_to_bv 64 rp) s8 s9 s10 s11
             (Z_to_bv 64 k) t4 t5 t6) F (Z_to_bv 64 0xb58a8) fc None m (seg_rom rsegs)).
