Definition dn_pass2_post (t4 t5 t6 a0 a1 a2 a3 a4 a5 a6 s0 s1 s5 s6 : word) (m : word -> option byte) (a z sh rp : Z) (w : word) : machine_state -> Prop :=
  fun ms' => exists (a' rp' c' : Z) (xs' : list word) (wa' : word) t4' t5' t6' m',
      ms' = MS (mkR ra sp gp tp (Z_to_bv 64 sh) (Z_to_bv 64 c') (Z_to_bv 64 (1000000000 / 2 ^ sh)) s0 s1 a0 a1 a2 a3 a4 a5 a6 (Z_to_bv 64 (2 ^ sh - 1)) (Z_to_bv 64 z) (Z_to_bv 64 a') s4 s5 s6 (Z_to_bv 64 rp') s8 s9 s10 s11
             (Z_to_bv 64 z) t4' t5' t6') F (Z_to_bv 64 0xb58dc) fc None m' (seg_rom rsegs)
      /\ munch [(X, X + 8192)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u32arr rsegs m' X xs' /\ length xs' = 2048%nat /\ w32 xs' /\ (0 <= c' < 1000000000)%Z /\ (0 <= a' < 2048)%Z
      /\ ((a' = a /\ rp' = rp /\ nth_error xs' (Z.to_nat a) = Some wa' /\ 1 <= bv_unsigned wa' < bv_unsigned w)%Z
          \/ (a' = (a + 1) mod 2048 /\ rp' = rp - 9 /\ bv_unsigned w < 2 ^ sh /\
              ((a' <> z /\ nth_error xs' (Z.to_nat a') = Some wa' /\ 1 <= bv_unsigned wa') \/ (a' = z /\ 1 <= c')))%Z).

