Definition dn_inv_post (m : word -> option byte) (rp : Z) (w : word) : machine_state -> Prop :=
  fun ms' => exists (a' z' rp' : Z) (xs' : list word) (wa' : word) t0' t1' t2' t3' t4' t5' t6' a0' a1' a2' a3' a4' a5' a7' s1' s5' s6' m',
      ms' = MS (mkR ra sp gp tp t0' t1' t2' (Z_to_bv 64 ((z' + 1) mod 2048)) s1' a0' a1' a2' a3' a4' a5' (Z_to_bv 64 (X + 4 * ((z' - 1) mod 2048))) a7'
                    (Z_to_bv 64 z') (Z_to_bv 64 a') s4 s5' s6' (Z_to_bv 64 rp') s8 s9 s10 s11 t3' t4' t5' t6') F
               (Z_to_bv 64 0xb577c) fc None m' (seg_rom rsegs)
      /\ munch [(X, X + 8192)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u32arr rsegs m' X xs' /\ length xs' = 2048%nat /\ w32 xs'
      /\ (0 <= a' < 2048)%Z /\ (0 <= z' < 2048)%Z /\ a' <> z'
      /\ nth_error xs' (Z.to_nat a') = Some wa' /\ (1 <= bv_unsigned wa')%Z
      /\ (36 <= rp' /\ rp' mod 9 = 0 /\ (rp' < rp \/ (rp' = rp /\ bv_unsigned wa' < bv_unsigned w)))%Z.

Lemma dn_round : forall (t0 t1 t2 t3 t4 t5 t6 a0 a1 a2 a3 a4 a5 a7 s1 s5 s6 : word) m (a z rp : Z) (xs : list word) (w : word),
  mem_inv rsegs m -> u32arr rsegs m X xs -> length xs = 2048%nat -> w32 xs ->
  (0 <= a < 2048)%Z -> (0 <= z < 2048)%Z -> a <> z -> (36 <= rp <= 4000)%Z -> (rp mod 9 = 0)%Z ->
  nth_error xs (Z.to_nat a) = Some w -> (1 <= bv_unsigned w)%Z -> (rp = 36 -> 2 <= bv_unsigned w)%Z ->
  evt rsegs (dn_inv_post m rp w)
    (MS (mkR ra sp gp tp t0 t1 t2 (Z_to_bv 64 ((z + 1) mod 2048)) s1 a0 a1 a2 a3 a4 a5 (Z_to_bv 64 (X + 4 * ((z - 1) mod 2048))) a7
             (Z_to_bv 64 z) (Z_to_bv 64 a) s4 s5 s6 (Z_to_bv 64 rp) s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0xb5840) fc None m (seg_rom rsegs)).
